toolUseResult.newString:
try {
  const initial = await runAttempt(sessionId ?? null);
  // Claude may report an unknown-session failure either in parsed JSON
  // (exit 0 + result text) or by exiting non-zero with the error in
  // stderr — detect both so the retry-with-fresh-session fallback fires.
  const unknownSessionFailure =
    sessionId &&
    !initial.proc.timedOut &&
    (initial.proc.exitCode ?? 0) !== 0 &&
    detectClaudeUnknownSession({
      parsed: initial.parsed,
      stdout: initial.proc.stdout,
      stderr: initial.proc.stderr,
    });

  // Diagnostic: confirms the new code path is loaded after `dev:cf` restart.
  // Logged unconditionally on a non-zero exit so it's easy to grep for.
  if (sessionId && (initial.proc.exitCode ?? 0) !== 0) {
    await onLog(
      "stdout",
      `[paperclip] claude exit=${initial.proc.exitCode} ` +
        `unknownSession=${unknownSessionFailure} sessionId=${sessionId}\n`,
    );
  }

  if (unknownSessionFailure) {
    await onLog(
      "stdout",
      `[paperclip] Claude resume session "${sessionId}" is unavailable; retrying with a fresh session.\n`,
    );
    const retry = await runAttempt(null);
    return toAdapterResult(retry, { fallbackSessionId: null, clearSessionOnMissingSession: true });
  }

  return toAdapterResult(initial, { fallbackSessionId: runtimeSessionId || runtime.sessionId });

